# Batch 5: campaign / benchmark ledger ("prior-work cards"). Each card: what was designed, outcome, failure modes, lessons.
# Fields not stated in the opened passages say so explicitly (no inference presented as fact). Quotes verified verbatim by build_kb.py on EC2.
from rules_raw_batch1 import add, R  # noqa

def card(id, pmcid, tier, summary, main_quote, quotes, method, modality, outcome, failure_modes, lessons, confidence="medium", scope=None, targets=None, notes=""):
    add(id=id, pmcid=pmcid, tier=tier, kind="card", scope=scope or ["design campaign"], outcome="campaign ledger",
        statement=summary, feat=None, direction="context", effect=None, quote=main_quote, quotes=quotes,
        confidence=confidence, notes=notes, applicable_target=targets,
        card=dict(method=method, modality=modality, outcome=outcome, failure_modes=failure_modes, lessons=lessons))

